import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
class DriverKycScreen extends StatefulWidget { const DriverKycScreen({super.key}); @override State<DriverKycScreen> createState()=>_DriverKycScreenState(); }
class _DriverKycScreenState extends State<DriverKycScreen>{
 final picker=ImagePicker(); final paths=<String,String?>{'driving_license':null,'vehicle_rc':null,'insurance':null};
 bool busy=false; String status='not_submitted',note='',message='';
 SupabaseClient get db=>Supabase.instance.client; String get uid=>db.auth.currentUser!.id;
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final r=await db.from('driver_kyc').select().eq('driver_id',uid).maybeSingle();if(r!=null&&mounted){setState((){status=r['verification_status']??'pending';note=r['admin_note']??'';paths['driving_license']=r['license_path'];paths['vehicle_rc']=r['vehicle_rc_path'];paths['insurance']=r['insurance_path'];});}}catch(e){if(mounted)setState(()=>message=e.toString());}}
 Future<void> upload(String key)async{final f=await picker.pickImage(source:ImageSource.gallery,imageQuality:80);if(f==null)return;setState(()=>busy=true);try{final bytes=await f.readAsBytes();if(bytes.length>10*1024*1024)throw Exception('Maximum 10 MB per file.');final ext=f.name.toLowerCase().endsWith('.png')?'png':'jpg';final path='$uid/$key-${DateTime.now().millisecondsSinceEpoch}.$ext';await db.storage.from('driver-kyc-private').uploadBinary(path,bytes,fileOptions:FileOptions(contentType:ext=='png'?'image/png':'image/jpeg'));if(mounted)setState(()=>paths[key]=path);}catch(e){if(mounted)setState(()=>message='Upload failed: $e');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> submit()async{if(paths.values.any((p)=>p==null)){setState(()=>message='Upload Licence, RC and Insurance first.');return;}setState(()=>busy=true);try{await db.from('driver_kyc').upsert({'driver_id':uid,'license_path':paths['driving_license'],'vehicle_rc_path':paths['vehicle_rc'],'insurance_path':paths['insurance'],'verification_status':'pending','admin_note':null,'submitted_at':DateTime.now().toUtc().toIso8601String()},onConflict:'driver_id');if(mounted)setState(()=>status='pending');}catch(e){if(mounted)setState(()=>message=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 Widget doc(String key,String label)=>Card(child:ListTile(title:Text(label),subtitle:Text(paths[key]==null?'Not uploaded':'Uploaded securely'),trailing:TextButton(onPressed:busy?null:()=>upload(key),child:const Text('Upload'))));
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Driver KYC verification')),body:ListView(padding:const EdgeInsets.all(16),children:[Text('Status: ${status.toUpperCase()}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),if(note.isNotEmpty)Text('Admin note: $note'),const Text('Documents are stored privately and reviewed by an administrator.'),doc('driving_license','Driving Licence'),doc('vehicle_rc','Vehicle RC'),doc('insurance','Vehicle Insurance'),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Please wait':'Submit for verification')),if(message.isNotEmpty)Text(message)]));
}
